solution.solution.cpp:
#include <cctype>
#include <map>
#include <string>

class KvServer
{
public:
    explicit KvServer(std::size_t maxQueued) : limit{ maxQueued } {}

    int accept() { connections[next] = {}; return next++; }

    void readable(int id, const std::string& bytes)
    {
        const auto it{ connections.find(id) };
        if (it == connections.end() || it->second.closing) return;
        Connection& c{ it->second };
        c.input += bytes;
        for (;;)
        {
            const std::size_t end{ c.input.find('\n') };
            if (end == std::string::npos)
            {
                if (c.input.size() >= 1024) connections.erase(it);
                return;
            }
            if (end > 1024) { connections.erase(it); return; }
            std::string line{ c.input.substr(0, end) };
            c.input.erase(0, end + 1);
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line == "QUIT")
            {
                c.closing = true;
                c.input.clear();
                if (!queue(c, "+BYE\n")) { connections.erase(it); return; }
                return;
            }
            if (!queue(c, handle(line) + "\n")) { connections.erase(it); return; }
        }
    }

    std::string writable(int id, std::size_t capacity)
    {
        const auto it{ connections.find(id) };
        if (it == connections.end()) return "";
        Connection& c{ it->second };
        std::string sent{ c.output.substr(0, capacity) };
        c.output.erase(0, sent.size());
        if (c.closing && c.output.empty()) connections.erase(it);
        return sent;
    }

    bool isOpen(int id) const { return connections.count(id) > 0; }
    std::size_t keyCount() const { return store.size(); }

private:
    struct Connection { std::string input, output; bool closing{ false }; };
    std::map<int, Connection> connections;
    std::map<std::string, std::string> store;
    std::size_t limit;
    int next{ 1 };

    bool queue(Connection& c, const std::string& reply)
    {
        if (c.output.size() + reply.size() > limit) return false;
        c.output += reply;
        return true;
    }

    static bool validKey(const std::string& k) { return !k.empty() && k.size() <= 64 && k.find(' ') == std::string::npos; }

    std::string handle(const std::string& line)
    {
        const std::size_t sp{ line.find(' ') };
        const std::string command{ line.substr(0, sp) };
        const std::string rest{ sp == std::string::npos ? "" : line.substr(sp + 1) };
        if (command == "KEYS")
        {
            if (!rest.empty()) return "-ERR bad request";
            std::string out{ "*" };
            bool first{ true };
            for (const auto& entry : store) { if (!first) out += ','; out += entry.first; first = false; }
            return out;
        }
        if (command != "SET" && command != "GET" && command != "DEL" && command != "INCR") return "-ERR unknown command";
        if (command == "SET")
        {
            const std::size_t sp2{ rest.find(' ') };
            if (sp2 == std::string::npos) return "-ERR bad request";
            const std::string key{ rest.substr(0, sp2) };
            if (!validKey(key)) return "-ERR bad request";
            store[key] = rest.substr(sp2 + 1);
            return "+OK";
        }
        if (!validKey(rest)) return "-ERR bad request";
        if (command == "GET")
        {
            const auto it{ store.find(rest) };
            return it == store.end() ? "-ERR no such key" : "$" + it->second;
        }
        if (command == "DEL") return store.erase(rest) ? ":1" : ":0";
        const auto it{ store.find(rest) };
        long long value{ 0 };
        if (it != store.end())
        {
            const std::string& v{ it->second };
            if (v.empty() || v.size() > 18) return "-ERR not a number";
            std::size_t i{ v[0] == '-' ? 1u : 0u };
            if (i == v.size()) return "-ERR not a number";
            for (; i < v.size(); ++i) if (!std::isdigit(static_cast<unsigned char>(v[i]))) return "-ERR not a number";
            value = std::stoll(v);
        }
        ++value;
        store[rest] = std::to_string(value);
        return ":" + std::to_string(value);
    }
};

unitTests:
static std::string drain(KvServer& s, int id) { return s.writable(id, 100000); }
TEST("set, get and delete") {
    KvServer s{ 4096 };
    const int a{ s.accept() };
    s.readable(a, "SET name Ada Lovelace\nGET name\nGET missing\nDEL name\nDEL name\n");
    CHECK_EQ(drain(s, a), std::string("+OK\n$Ada Lovelace\n-ERR no such key\n:1\n:0\n"));
}
TEST("requests split anywhere") {
    KvServer s{ 4096 };
    const int a{ s.accept() };
    const std::string stream{ "SET k v\r\nGET k\r\n" };
    for (char ch : stream) s.readable(a, std::string(1, ch));
    CHECK_EQ(drain(s, a), std::string("+OK\n$v\n"));
}
TEST("a shared store") {
    KvServer s{ 4096 };
    const int a{ s.accept() }, b{ s.accept() };
    s.readable(a, "SET score 10\n");
    s.readable(b, "INCR score\nINCR fresh\nKEYS\n");
    CHECK_EQ(drain(s, b), std::string(":11\n:1\n*fresh,score\n"));
    CHECK_EQ(s.keyCount(), 2u);
    s.readable(a, "SET name x\nINCR name\nSET n -5\nINCR n\n");
    CHECK_EQ(drain(s, a), std::string("+OK\n+OK\n-ERR not a number\n+OK\n:-4\n"));
}
TEST("bad requests") {
    KvServer s{ 4096 };
    const int a{ s.accept() };
    s.readable(a, "SET onlykey\nGET\nFLY away\nKEYS extra\n");
    CHECK_EQ(drain(s, a), std::string("-ERR bad request\n-ERR bad request\n-ERR unknown command\n-ERR bad request\n"));
    s.readable(a, "KEYS\n");
    CHECK_EQ(drain(s, a), std::string("*\n"));
}
TEST("partial writes and quitting") {
    KvServer s{ 4096 };
    const int a{ s.accept() };
    s.readable(a, "GET x\nQUIT\nGET y\n");
    CHECK_EQ(s.writable(a, 5), std::string("-ERR "));
    CHECK(s.isOpen(a));
    CHECK_EQ(s.writable(a, 100), std::string("no such key\n+BYE\n"));
    CHECK(!s.isOpen(a));
}
TEST("limits") {
    KvServer s{ 4096 };
    const int a{ s.accept() };
    s.readable(a, std::string(1025, 'x') + "\n");
    CHECK(!s.isOpen(a));
    const int b{ s.accept() };
    s.readable(b, std::string(1024, 'y'));
    CHECK(!s.isOpen(b));
    KvServer small{ 20 };
    const int c{ small.accept() };
    small.readable(c, "SET k 0123456789\nGET k\nGET k\n");
    CHECK(!small.isOpen(c));
}

